#include <Arduino.h>
#include <DHT.h>
#include <TM1637Display.h>
#include <math.h>

DHT dht(7, DHT11);
TM1637Display display(4, 3);
int people = 0;
float temperatureC = 25;
bool showTemperature = false;
bool previousA = false, previousB = false;
int firstSensor = 0;
unsigned long sequenceStarted = 0;
unsigned long lastSensors = 0, lastDht = 0;
bool rawButton = HIGH, stableButton = HIGH;
unsigned long buttonChanged = 0;

bool nearSensor(uint8_t trigger, uint8_t echo) {
  digitalWrite(trigger, LOW);
  delayMicroseconds(2);
  digitalWrite(trigger, HIGH);
  delayMicroseconds(10);
  digitalWrite(trigger, LOW);
  unsigned long duration = pulseIn(echo, HIGH, 25000UL);
  return duration != 0 && duration * 0.0343f / 2.0f < 30.0f;
}

void passageEdge(int sensor, unsigned long now) {
  if (firstSensor == 0) {
    firstSensor = sensor;
    sequenceStarted = now;
  } else if (firstSensor != sensor) {
    if (firstSensor == 1) {
      if (people < 9999) ++people;
    } else if (people > 0) {
      --people;
    }
    firstSensor = 0;
    Serial.print("Population: ");
    Serial.println(people);
  }
}

void setup() {
  pinMode(8, OUTPUT);
  pinMode(9, INPUT);
  pinMode(10, OUTPUT);
  pinMode(11, INPUT);
  pinMode(2, INPUT_PULLUP);
  pinMode(5, OUTPUT);
  analogWrite(5, 0);
  Serial.begin(9600);
  dht.begin();
  display.setBrightness(7);
  display.showNumberDec(people);
  lastDht = millis() - 2000UL;
}

void loop() {
  unsigned long now = millis();
  bool button = digitalRead(2);
  if (button != rawButton) {
    rawButton = button;
    buttonChanged = now;
  }
  if (now - buttonChanged >= 40 && stableButton != rawButton) {
    stableButton = rawButton;
    if (stableButton == LOW) showTemperature = !showTemperature;
  }
  if (now - lastDht >= 2000) {
    lastDht = now;
    float t = dht.readTemperature();
    if (!isnan(t)) temperatureC = t;
  }
  if (firstSensor != 0 && now - sequenceStarted > 2000) firstSensor = 0;
  if (now - lastSensors >= 80) {
    lastSensors = now;
    bool a = nearSensor(8, 9);
    bool b = nearSensor(10, 11);
    if (a && !previousA) passageEdge(1, now);
    if (b && !previousB) passageEdge(2, now);
    previousA = a;
    previousB = b;
  }
  int pwm = 0;
  if (people > 0) {
    pwm = constrain((int)(temperatureC - 18) * 8 + people * 12, 0, 255);
  }
  analogWrite(5, pwm);
  display.showNumberDec(showTemperature ? (int)round(temperatureC) : people);
  delay(5);
}
